// HTTP Markdown content negotiation for SENO avian docs (data.aviantestpro.com)
//
// Serves the Markdown sidecar generated by scripts/generate-md.py when a
// request prefers text/markdown over text/html (strictly higher q).
// HTML remains the default for everything else, including missing sidecars.
//
// Negotiation policy (deterministic):
//   - Parse Accept header media ranges + q-values.
//   - text/markdown wins only when q(md) > max(q(html), q(*/*)).
//   - Ties and q=0 fall back to normal HTML (HTML is canonical).
//   - Non-GET/HEAD, non-document paths, and missing manifest entries -> pass through.
//
// Cache policy:
//   - Markdown responses: Cache-Control: no-store (until cache separation is
//     verified in production).
//   - HTML responses: existing cache behavior preserved; Vary: Accept is
//     appended so downstream caches key representations separately.

let manifestPromise = null;

function parseAccept(header) {
  const out = new Map();
  if (!header) return out;
  for (const part of header.split(",")) {
    const segments = part.trim().split(";");
    const type = (segments[0] || "").trim().toLowerCase();
    if (!type) continue;
    let q = 1;
    for (const seg of segments.slice(1)) {
      const m = seg.trim().match(/^q=(\d+(?:\.\d+)?)$/i);
      if (m) {
        q = parseFloat(m[1]);
        break;
      }
    }
    out.set(type, q);
  }
  return out;
}

function wantsMarkdown(acceptHeader) {
  const q = parseAccept(acceptHeader);
  const mdQ = q.get("text/markdown") || 0;
  if (mdQ <= 0) return false;
  const htmlQ = q.has("text/html") ? q.get("text/html") : -1;
  const anyQ = q.has("*/*") ? q.get("*/*") : -1;
  return mdQ > Math.max(htmlQ, anyQ);
}

// Canonical form: trailing slash (matches MkDocs directory URLs).
function normalizePath(pathname) {
  if (pathname.length > 1 && !pathname.endsWith("/")) return pathname + "/";
  return pathname;
}

async function getManifest(env) {
  if (!manifestPromise) {
    manifestPromise = (async () => {
      try {
        const res = await env.ASSETS.fetch(new Request("https://internal/_md/manifest.json"));
        if (!res.ok) return null;
        return await res.json();
      } catch {
        return null;
      }
    })();
  }
  try {
    return await manifestPromise;
  } catch {
    return null;
  }
}

export async function onRequest(context) {
  const { request, next, env } = context;
  const url = new URL(request.url);

  if (request.method !== "GET" && request.method !== "HEAD") {
    return next();
  }

  const accept = request.headers.get("Accept") || "";

  if (wantsMarkdown(accept)) {
    const manifest = await getManifest(env);
    if (manifest) {
      const pathname = url.pathname;
      const mdRel = manifest[normalizePath(pathname)] || manifest[pathname];
      if (mdRel) {
        try {
          const mdRes = await env.ASSETS.fetch(new Request(new URL(mdRel, url).toString()));
          if (mdRes.ok) {
            const body = await mdRes.text();
            return new Response(body, {
              status: 200,
              headers: {
                "Content-Type": "text/markdown; charset=utf-8",
                "Vary": "Accept",
                "Cache-Control": "no-store",
              },
            });
          }
        } catch {
          // fall through to normal HTML
        }
      }
    }
  }

  const res = await next();

  // Document responses participate in negotiation: ensure Vary: Accept so
  // downstream caches never mix HTML and Markdown representations.
  const ct = res.headers.get("Content-Type") || "";
  if (ct.includes("text/html")) {
    res.headers.append("Vary", "Accept");
  }
  return res;
}
